import{useEffect,useState,useRef}from'react';
import type{ClientPluginContext,ViewProps}from'@aork/sdk/client';
import{readWorkbenchSelection}from'@aork/contracts/workspace';
import{nativeHistoryPageSchema,type NativeHistoryPage}from'@aork/contracts/recovery';
function useSelected(){const[id,setId]=useState(()=>readWorkbenchSelection(location.hash).sessionId);useEffect(()=>{const change=()=>setId(readWorkbenchSelection(location.hash).sessionId);addEventListener('hashchange',change);return()=>removeEventListener('hashchange',change);},[]);return id;}
function Recovery({runtime}:ViewProps){const id=useSelected();const[error,setError]=useState('');const command=useRef<string|undefined>(undefined);return id?<section><h3>独立原生恢复</h3><button onClick={async()=>{command.current??=crypto.randomUUID();try{await runtime.command('sessions.recoverNative',{sessionId:id},command.current,{version:1});command.current=undefined;}catch(failure){setError(String(failure));}}}>独立恢复</button>{error&&<p role="alert">{error}</p>}</section>:null;}
function History({runtime}:ViewProps){const id=useSelected();const[page,setPage]=useState<NativeHistoryPage>();const[error,setError]=useState('');useEffect(()=>{setPage(undefined);if(!id)return;const stop=runtime.observeSnapshot('sessions.nativeHistory',{sessionId:id},{next(value){setPage(nativeHistoryPageSchema.parse(value));},error(failure){setError(failure.message);}},{owners:['sessions']});return()=>{void stop();};},[runtime,id]);return<section aria-label="独立原生历史"><h3>独立原生历史</h3>{page?.entries.map(entry=><p key={entry.id}>{entry.text}</p>)}{error&&<p role="alert">{error}</p>}</section>;}
export function activate(context:ClientPluginContext){context.registerView('recovery',Recovery);context.registerView('native-history',History);}
